1	/** A live cell's position as [x, y] grid coordinates. */
2	type Cell = [number, number];
3	
4	/** A cell serialized as an "x,y" string, usable as a Set/Map key. */
5	type CellKey = string;
6	
7	const toKey = ([x, y]: Cell): CellKey => `${x},${y}`;
8	const fromKey = (key: CellKey): Cell => key.split(",").map(Number) as Cell;
9	
10	/** The 8 offsets from a cell to each of its surrounding neighbors. */
11	const NEIGHBOR_OFFSETS: Cell[] = [
12	  [-1, -1], [0, -1], [1, -1],
13	  [-1, 0], [1, 0],
14	  [-1, 1], [0, 1], [1, 1],
15	];
16	
17	/**
18	 * Conway's rules: a cell is alive next generation if it has exactly 3 live
19	 * neighbors (birth / survival) or is already alive with exactly 2 (survival).
20	 */
21	const isAliveNextGen = (liveNeighbors: number, isCurrentlyLive: boolean): boolean =>
22	  liveNeighbors === 3 || (liveNeighbors === 2 && isCurrentlyLive);
23	
24	/**
25	 * Tallies, for every cell adjacent to a live cell, how many live neighbors it
26	 * has. Cells absent from the map have zero live neighbors and can never come
27	 * alive, so they need no consideration next generation.
28	 */
29	const tallyNeighbors = (cells: Cell[]): Map<CellKey, number> => {
30	  const neighborCounts = new Map<CellKey, number>();
31	  for (const [x, y] of cells) {
32	    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
33	      const key = toKey([x + dx, y + dy]);
34	      neighborCounts.set(key, (neighborCounts.get(key) ?? 0) + 1);
35	    }
36	  }
37	  return neighborCounts;
38	};
39	
40	export function nextGeneration(cells: Cell[]): Cell[] {
41	  const live = new Set(cells.map(toKey));
42	
43	  const next: Cell[] = [];
44	  for (const [key, count] of tallyNeighbors(cells)) {
45	    if (isAliveNextGen(count, live.has(key))) {
46	      next.push(fromKey(key));
47	    }
48	  }
49	  return next;
50	}
