1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  // Simplest cases
6	  it("empty grid stays empty — [] → []", () => {
7	    expect(nextGeneration([])).toEqual([]);
8	  });
9	  it("single cell dies (underpopulation) — [(0,0)] → []", () => {
10	    expect(nextGeneration([[0, 0]])).toEqual([]);
11	  });
12	
13	  // Rule 1 – Underpopulation (live cell with < 2 neighbors dies)
14	  it("two adjacent cells both die — [(0,1),(1,1)] → []", () => {
15	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
16	  });
17	
18	  // Rule 2 – Survival (live cell with 2 or 3 neighbors lives on)
19	  it("live cell with 2 neighbors survives — (1,0) stays alive", () => {
20	    // Gen0: ### / ... / .#.  → live cell (1,0) has 2 live neighbors: (0,0) and (2,0)
21	    const next = nextGeneration([[0, 0], [1, 0], [2, 0], [1, 2]]);
22	    expect(next).toContainEqual([1, 0]);
23	  });
24	
25	  // Rule 4 – Reproduction (dead cell with exactly 3 neighbors becomes alive)
26	  it("dead cell with exactly 3 neighbors becomes alive — (1,1) born", () => {
27	    // Gen0: ##. / #.. / ...  → dead cell (1,1) has 3 live neighbors: (0,0),(1,0),(0,1)
28	    const next = nextGeneration([[0, 0], [1, 0], [0, 1]]);
29	    expect(next).toContainEqual([1, 1]);
30	  });
31	
32	  // Rule 3 – Overpopulation (live cell with > 3 neighbors dies)
33	  it("center cell with 4 neighbors dies — (1,1) removed in next gen", () => {
34	    // Gen0: ### / .#. / ###  → center (1,1) has 4 live neighbors
35	    const next = nextGeneration([[0, 0], [1, 0], [2, 0], [1, 1], [0, 2], [1, 2], [2, 2]]);
36	    expect(next).not.toContainEqual([1, 1]);
37	  });
38	
39	  // Pattern examples
40	  it("block still life is unchanged — [(0,0),(1,0),(0,1),(1,1)] stays the same", () => {
41	    const next = nextGeneration([[0, 0], [1, 0], [0, 1], [1, 1]]);
42	    expect(next).toHaveLength(4);
43	    expect(next).toContainEqual([0, 0]);
44	    expect(next).toContainEqual([1, 0]);
45	    expect(next).toContainEqual([0, 1]);
46	    expect(next).toContainEqual([1, 1]);
47	  });
48	  it("blinker oscillates — [(0,0),(0,1),(0,2)] → [(-1,1),(0,1),(1,1)]", () => {
49	    const next = nextGeneration([[0, 0], [0, 1], [0, 2]]);
50	    expect(next).toHaveLength(3);
51	    expect(next).toContainEqual([-1, 1]);
52	    expect(next).toContainEqual([0, 1]);
53	    expect(next).toContainEqual([1, 1]);
54	    expect(next).not.toContainEqual([0, 0]);
55	    expect(next).not.toContainEqual([0, 2]);
56	  });
57	
58	  // Negative coordinates
59	  it.todo("handles negative coordinates — blinker gen1 back to gen0 orientation");
60	});
