export function nextGeneration(cells: Cell[]): Cell[] {
  const liveCells = new Set(cells.map(toKey));

  return [...tallyNeighbors(cells)]
    .filter(([key, count]) => isAliveNextGen(count, liveCells.has(key)))
    .map(([key]) => fromKey(key));
}
